python3 -c "
import json, sys, subprocess, os
data = json.load(sys.stdin)
fp = data.get('tool_input', {}).get('file_path', '')
ext = os.path.splitext(fp)[1].lower()
convertible = {'.pdf','.docx','.doc','.xlsx','.xls','.pptx','.ppt','.jpg','.jpeg','.png','.gif','.bmp','.wav','.mp3','.mp4','.avi','.mov'}
if ext in convertible and os.path.exists(fp):
    result = subprocess.run(['markitdown', fp], capture_output=True, text=True)
    if result.returncode == 0:
        out = {'hookSpecificOutput': {'hookEventName': 'PreToolUse', 'additionalContext': '[MarkItDown] Converted ' + fp + ':\n\n' + result.stdout}}
        print(json.dumps(out))
" 2>/dev/null || true
